#!/usr/bin/env python3
"""Explicit NARR reproduction helper: init / validate / plan / status (stdlib only).

Usage (never needs a project environment):

    uv run --no-project python workflow.py init WORKSPACE --mode narr-reproduction
    uv run --no-project python workflow.py validate --config WORKSPACE/mpm-config.json
    uv run --no-project python workflow.py plan --config WORKSPACE/mpm-config.json [--apply]
    uv run --no-project python workflow.py status --workspace WORKSPACE

What it does
  init      Create a user workspace. Copies the pinned reference pipeline
            (references/upstream) to WORKSPACE/pipeline and a config template to
            WORKSPACE/mpm-config.json. The installed skill is never edited.
  validate  Check the user's CSV against the JSON config: columns, PU labels,
            projected CRS declaration, coordinate units, explicit feature
            selection and units, missingness, duplicate coordinates, spatial
            block and positive support. Writes validation-report.json.
  plan      Re-run validate, then write plan.md / plan.json with the actual
            stage commands, adaptation-needed items and unvalidated points.
            With --apply, also renders WORKSPACE/pipeline/config/config.yaml.
  status    Show which stage artifacts exist and whether data/config changed
            since the plan (the reference pipeline skips stages by file
            existence only).

What it does NOT do
  It never modifies or copies the source CSV, never installs packages, never
  trains a model and never starts a pipeline stage. A passing validate means
  "the declared contract matches the file", not "the science is sound".

Exit codes: 0 ok, 1 validation errors / blocked plan, 2 usage or I/O error.
"""

import argparse
import csv
import hashlib
import json
import math
import os
import shutil
import sys
from datetime import datetime, timezone
from pathlib import Path

CASE_ROOT = Path(__file__).resolve().parent.parent  # reference-cases/narr-yilgarn
SKILL_ROOT = CASE_ROOT.parent.parent
UPSTREAM_DIR = SKILL_ROOT / "references" / "upstream"
TEMPLATE_PATH = CASE_ROOT / "assets" / "narr-reproduction-config.template.json"

SCHEMA_VERSION = 1
UNIT_TO_METRE = {"m": 1.0, "km": 1000.0, "ft": 0.3048, "us-ft": 1200.0 / 3937.0}
METHODS = ("xgboost", "baggingpu_xgboost")
CONFORMAL_PATHS = ("default", "pooled_oof", "both")

# Keys the reference scripts read from config.yaml but that do not describe the
# user's data. Values are the reference study's settings, kept so the copied
# code runs; they are not recommendations for a new area.
REFERENCE_STATIC_CONFIG = {
    "output_dirs": {
        "folds": "outputs/folds",
        "optuna": "outputs/optuna",
        "models": "outputs/models",
        "conformal": "outputs/conformal",
        "test_evaluation": "outputs/test_evaluation",
        "aggregated": "outputs/aggregated",
        "figures": "outputs/figures",
        "reports": "reports",
    },
    "zone_method": "jorc30",
    "practical_zone_modes": ["prob", "lift"],
    "zone_thresholds": {
        "jorc30": {"rel_iqr_threshold": 0.30, "prob_z0": 0.50, "prob_z1": 0.25, "prob_z2": 0.10},
        "lift": {"rel_iqr_threshold": 0.30, "lift_z0": 0.01, "lift_z1": 0.05, "lift_z2": 0.10},
        "percentile_std": {
            "prob_percentile_high": 98, "prob_percentile_mod": 90, "prob_percentile_low": 70,
            "std_low": 0.0765, "std_moderate": 0.1020, "std_high": 0.1276,
        },
    },
    "zone_definitions": {
        0: {"name": "IMMEDIATE", "description": "prob tier 0 AND rel_IQR <= threshold", "color": "#d62728"},
        1: {"name": "PRIORITY", "description": "high prob OR mid prob with low dispersion", "color": "#ff7f0e"},
        2: {"name": "FOLLOW_UP", "description": "mid prob OR low-mid prob with low dispersion", "color": "#ffbb78"},
        3: {"name": "POTENTIAL", "description": "remaining in_set_1 samples", "color": "#2ca02c"},
        4: {"name": "EXCLUDED", "description": "in_set_1 = 0", "color": "#9467bd"},
    },
    "visualization": {
        "figure_formats": ["png", "pdf"], "dpi": 300,
        "figsize_single": [8, 6], "figsize_wide": [12, 6], "figsize_map": [10, 10],
        "colormap_prob": "magma", "colormap_std": "viridis",
        "colormap_zone": ["#d62728", "#ff7f0e", "#ffbb78", "#2ca02c", "#9467bd"],
    },
    "logging": {
        "level": "INFO",
        "format": "%(asctime)s - %(name)s - %(levelname)s - %(message)s",
        "file_logging": True,
        "log_dir": "logs",
    },
}


class UsageError(Exception):
    pass


# --------------------------------------------------------------------------
# small utilities
# --------------------------------------------------------------------------

def now_iso():
    return datetime.now(timezone.utc).isoformat(timespec="seconds")


def sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def load_json_file(path):
    try:
        with open(path, "r", encoding="utf-8") as handle:
            return json.load(handle)
    except FileNotFoundError:
        raise UsageError(f"file not found: {path}")
    except json.JSONDecodeError as exc:
        raise UsageError(f"invalid JSON in {path}: {exc}")


def write_json_file(path, payload):
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2, ensure_ascii=False)
        handle.write("\n")


def rel_to(path, base):
    """A path as recorded in helper outputs: relative to the recording file's directory, never absolute."""
    if path is None:
        return None
    return os.path.relpath(Path(path), Path(base))


def report_for_disk(report, base):
    """The validation report with its input paths made relative to the directory it is written to."""
    return {**report, "paths_relative_to": "this file's directory",
            "config_path": rel_to(report["config_path"], base), "csv_path": rel_to(report["csv_path"], base)}


def is_blank(value):
    return value is None or (isinstance(value, str) and value.strip() == "")


def to_float(text):
    try:
        value = float(text)
    except (TypeError, ValueError):
        return None
    return value if math.isfinite(value) else None


def same_value(cell, declared):
    """Compare a CSV cell with a declared label value (numeric when possible)."""
    a, b = to_float(cell), to_float(declared)
    if a is not None and b is not None:
        return a == b
    return str(cell).strip() == str(declared).strip()


def yaml_scalar(value):
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    return json.dumps(str(value), ensure_ascii=False)  # JSON string == YAML double-quoted


def to_yaml(value, indent=0):
    """Minimal block-style YAML emitter for dict / list / scalar trees."""
    pad = "  " * indent
    lines = []
    if isinstance(value, dict):
        for key, item in value.items():
            key_text = str(key) if isinstance(key, int) else yaml_scalar(key)
            if isinstance(item, dict) and item:
                lines.append(f"{pad}{key_text}:")
                lines.extend(to_yaml(item, indent + 1))
            elif isinstance(item, list) and item and any(isinstance(x, (dict, list)) for x in item):
                lines.append(f"{pad}{key_text}:")
                lines.extend(to_yaml(item, indent + 1))
            elif isinstance(item, list):
                lines.append(f"{pad}{key_text}: [{', '.join(yaml_scalar(x) for x in item)}]")
            elif isinstance(item, dict):
                lines.append(f"{pad}{key_text}: {{}}")
            else:
                lines.append(f"{pad}{key_text}: {yaml_scalar(item)}")
    elif isinstance(value, list):
        for item in value:
            if isinstance(item, (dict, list)):
                sub = to_yaml(item, indent + 1)
                lines.append(f"{pad}- {sub[0].lstrip()}")
                lines.extend(sub[1:])
            else:
                lines.append(f"{pad}- {yaml_scalar(item)}")
    return lines


class Findings:
    def __init__(self):
        self.items = []
        self.crs_check = None

    def add(self, level, code, message):
        self.items.append({"level": level, "code": code, "message": message})

    def error(self, code, message):
        self.add("error", code, message)

    def warn(self, code, message):
        self.add("warning", code, message)

    def info(self, code, message):
        self.add("info", code, message)

    def count(self, level):
        return sum(1 for item in self.items if item["level"] == level)


# --------------------------------------------------------------------------
# init
# --------------------------------------------------------------------------

WORKSPACE_README = """# MPM workspace

Created by the reference-case reproduction helper. Everything here is yours to edit;
the installed skill and your source data are never modified by the helper.

- `mpm-config.json`  dataset contract. Fill every empty string / null. The
  helper does not guess column names, labels, CRS or units.
- `pipeline/`        copy of the pinned reference research code (MIT, see
  pipeline/LICENSE). Its shipped config/config.yaml is the reference study's
  (Yilgarn Ni) setting; the untouched original is config/config.reference-study.yaml.
  Adapt this copy, not the skill. Record every change in `adaptations.md`.
- `adaptations.md`   log of code changes you (or the agent) make to pipeline/.
- `validation-report.json`, `plan.md`, `plan.json`  written by validate / plan.

Commands (HELPER = path printed by init):

    uv run --no-project python HELPER validate --config mpm-config.json
    uv run --no-project python HELPER plan --config mpm-config.json
    uv run --no-project python HELPER plan --config mpm-config.json --apply
    uv run --no-project python HELPER status --workspace .

`plan --apply` renders pipeline/config/config.yaml from mpm-config.json. Stage
commands listed in plan.md run inside pipeline/ with `uv run python ...`; the
first such run makes uv create pipeline/.venv from pipeline/uv.lock (local to
this workspace, needs network or a warm uv cache). The helper never does this
for you and never starts training.

A passing validate is a data-contract check. It is not evidence that the
reference method is appropriate for your area, commodity or labels.
"""

ADAPTATIONS_HEADER = """# Adaptations to pipeline/

Record each change to the copied reference code: date, file, what and why,
and how it was checked. Unrecorded changes make results irreproducible.

| date | file | change | reason | check |
|------|------|--------|--------|-------|
"""


def cmd_init(args):
    if args.mode != "narr-reproduction":
        raise UsageError("This helper only supports explicit NARR reproduction")
    workspace = Path(args.workspace).expanduser().resolve()
    if not UPSTREAM_DIR.is_dir():
        raise UsageError(f"reference code not found in skill: {UPSTREAM_DIR}")
    if not TEMPLATE_PATH.is_file():
        raise UsageError(f"config template not found in skill: {TEMPLATE_PATH}")
    try:
        workspace.relative_to(SKILL_ROOT)
    except ValueError:
        pass
    else:
        raise UsageError("workspace must be outside the installed skill directory")

    pipeline_dir = workspace / "pipeline"
    config_path = workspace / "mpm-config.json"
    existing = [p for p in (pipeline_dir, config_path, workspace / "workspace.json") if p.exists()]
    if existing:
        raise UsageError(
            "refusing to overwrite existing workspace content: "
            + ", ".join(str(p) for p in existing)
            + " (choose a new directory or remove these yourself)"
        )

    workspace.mkdir(parents=True, exist_ok=True)
    shutil.copytree(
        UPSTREAM_DIR, pipeline_dir,
        ignore=shutil.ignore_patterns("__pycache__", "*.pyc", ".venv", "outputs", "data", "logs"),
    )
    reference_config = pipeline_dir / "config" / "config.yaml"
    if reference_config.is_file():
        shutil.copy2(reference_config, pipeline_dir / "config" / "config.reference-study.yaml")
    shutil.copy2(TEMPLATE_PATH, config_path)
    if not (workspace / "README.md").exists():
        (workspace / "README.md").write_text(WORKSPACE_README, encoding="utf-8")
    adaptations = workspace / "adaptations.md"
    if not adaptations.exists():
        adaptations.write_text(ADAPTATIONS_HEADER, encoding="utf-8")

    provenance = {}
    provenance_path = UPSTREAM_DIR / "SOURCE.json"
    if provenance_path.is_file():
        provenance = load_json_file(provenance_path)
    code_hashes = {
        str(p.relative_to(pipeline_dir)): sha256_file(p)
        for p in sorted(pipeline_dir.rglob("*"))
        if p.is_file() and p.suffix in (".py", ".yaml", ".toml", ".lock")
    }
    write_json_file(workspace / "workspace.json", {
        "schema_version": SCHEMA_VERSION,
        "created": now_iso(),
        "helper": "reference-cases/narr-yilgarn/scripts/workflow.py",
        "helper_sha256": sha256_file(Path(__file__)),
        "reference_provenance": provenance,
        "pipeline_file_sha256_at_init": code_hashes,
    })

    print(f"workspace created: {workspace}")
    print(f"  reference code copy : {pipeline_dir}")
    print(f"  config to fill      : {config_path}")
    print(f"  helper              : {Path(__file__).resolve()}")
    print("next: fill mpm-config.json, then run validate. Nothing was installed or trained.")
    return 0


# --------------------------------------------------------------------------
# validate
# --------------------------------------------------------------------------

# Used only when pyproj cannot be imported (stdlib run); not a complete list.
FALLBACK_GEOGRAPHIC_CRS = ("EPSG:4326", "EPSG:4269", "EPSG:4283", "EPSG:7844", "CRS:84", "WGS84")
FALLBACK_MERCATOR_CRS = ("EPSG:3857", "EPSG:900913", "EPSG:3395")
AXIS_UNIT_TO_DECLARED = {"metre": "m", "meter": "m", "kilometre": "km", "kilometer": "km",
                         "foot": "ft", "us survey foot": "us-ft"}
MERCATOR_WARNING = (
    "is a normal-aspect Mercator CRS: coordinate distances are inflated by about 1/cos(latitude); "
    "block sizes and cell areas in coordinate units are not ground distances/areas. Record the "
    "latitude range and state the ground-equivalent block size, or use a regional projected CRS."
)


def check_crs_properties(crs_value, declared_unit, findings, verified_by=None):
    """Judge the declared CRS by its properties, not by a list of codes.

    Records findings.crs_check = {backend, status, ...}. Status is one of
    verified (pyproj parsed a projected 2D CRS), declared-unverified (no pyproj:
    only a short fallback list was checked), declared-verified-externally
    (no pyproj, but coordinates.crs_verified_by names an independent check) or
    invalid. Import absence and parse failure are different outcomes.
    """
    try:
        import pyproj
        from pyproj import CRS
    except ImportError:
        pyproj = CRS = None
    text = str(crs_value)
    if CRS is None:
        check = {"backend": "none (pyproj not importable)", "crs": text, "status": "declared-unverified"}
        compact = text.upper().replace(" ", "")
        if compact in FALLBACK_GEOGRAPHIC_CRS:
            findings.error("coordinates.crs", f"{text} is geographic (degrees), not projected")
            check["status"] = "invalid"
        if compact in FALLBACK_MERCATOR_CRS:
            findings.warn("coordinates.web_mercator", f"{text} {MERCATOR_WARNING}")
        if check["status"] == "declared-unverified":
            if not is_blank(verified_by):
                check.update(status="declared-verified-externally", verified_by=str(verified_by))
            findings.info("coordinates.crs_properties_unchecked",
                          "pyproj is not importable in this run; CRS type/units were checked only against a short "
                          "list. plan marks this as a blocker and refuses --apply unless coordinates.crs_verified_by "
                          "names an independent check (for example the GIS layer properties or a pyproj run).")
        findings.crs_check = check
        return
    check = {"backend": f"pyproj {pyproj.__version__}", "crs": text}
    try:
        crs = CRS.from_user_input(text)
    except Exception as exc:  # pyproj raises CRSError; keep the helper free of pyproj imports at load time
        findings.error("coordinates.crs", f"{text} is not a CRS that pyproj recognises: {exc}")
        findings.crs_check = {**check, "status": "invalid", "reason": "unparsable"}
        return
    check["name"] = crs.name
    if crs.is_compound:
        findings.error("coordinates.crs", f"{text} ({crs.name}) is a compound CRS; declare its horizontal projected CRS")
        findings.crs_check = {**check, "status": "invalid", "reason": "compound"}
        return
    if crs.is_geographic or not crs.is_projected:
        kind = "geographic" if crs.is_geographic else crs.type_name
        findings.error("coordinates.crs", f"{text} ({crs.name}) is {kind}, not a projected 2D CRS")
        findings.crs_check = {**check, "status": "invalid", "reason": kind}
        return
    method = crs.coordinate_operation.method_name if crs.coordinate_operation else ""
    axes = [(axis.direction, AXIS_UNIT_TO_DECLARED.get((axis.unit_name or "").lower(), axis.unit_name))
            for axis in crs.axis_info]
    check.update(status="verified", method=method, axes=[{"direction": d, "unit": u} for d, u in axes])
    if "mercator" in method.lower() and "transverse" not in method.lower():
        findings.warn("coordinates.web_mercator", f"{text} ({method}) {MERCATOR_WARNING}")
    axis_units = {u for _, u in axes}
    if declared_unit in UNIT_TO_METRE and axis_units and axis_units != {declared_unit}:
        findings.warn("coordinates.unit_mismatch",
                      f"coordinates.unit '{declared_unit}' differs from the axis unit of {text}: {sorted(map(str, axis_units))}. "
                      "Declare the unit of the coordinate columns actually supplied and record any rescaling.")
    if axes and str(axes[0][0]).lower() in ("north", "south"):
        findings.warn("coordinates.axis_order",
                      f"{text} lists a northing axis first; confirm that coordinates.x_column holds easting values.")
    findings.crs_check = check


def check_config_shape(config, findings):
    """Check declared values only (no file access). Returns normalised dict or None."""
    if not isinstance(config, dict):
        findings.error("config.type", "config root must be a JSON object")
        return None
    if config.get("analysis_mode") != "narr-reproduction":
        findings.error("config.analysis_mode", "Explicit analysis_mode=narr-reproduction required; this is not the general MPM entrypoint")
    if config.get("schema_version") != SCHEMA_VERSION:
        findings.error("config.schema_version", f"schema_version must be {SCHEMA_VERSION}")

    def section(name):
        value = config.get(name)
        if not isinstance(value, dict):
            findings.error(f"{name}.missing", f"section '{name}' is missing or not an object")
            return {}
        return value

    data, coords, label = section("data"), section("coordinates"), section("label")
    features, cv = section("features"), section("spatial_cv")
    grid = config.get("grid") if isinstance(config.get("grid"), dict) else {}
    conformal = config.get("conformal") if isinstance(config.get("conformal"), dict) else {}

    if is_blank(data.get("csv_path")):
        findings.error("data.csv_path", "data.csv_path is empty")
    tokens = data.get("missing_tokens")
    if not isinstance(tokens, list) or not all(isinstance(t, str) for t in tokens):
        findings.error("data.missing_tokens", "data.missing_tokens must be a list of strings (use [\"\"] for empty cells only)")
        tokens = [""]

    for key in ("x_column", "y_column", "crs", "unit"):
        if is_blank(coords.get(key)):
            findings.error(f"coordinates.{key}", f"coordinates.{key} is empty; it must be declared, not guessed")
    unit = coords.get("unit")
    if not is_blank(unit) and unit not in UNIT_TO_METRE:
        findings.error(
            "coordinates.unit",
            f"coordinates.unit '{unit}' not supported; use one of {sorted(UNIT_TO_METRE)}. "
            "Degrees are not a distance unit: reproject to a projected CRS first.",
        )
    if coords.get("projected") is not True:
        findings.error(
            "coordinates.projected",
            "coordinates.projected must be true. Spatial blocks are cut in coordinate units, so a "
            "geographic (lon/lat) CRS is not accepted. Reproject in GIS and keep the original file.",
        )
    if not is_blank(coords.get("crs")):
        check_crs_properties(coords.get("crs"), unit, findings, coords.get("crs_verified_by"))

    if is_blank(label.get("column")):
        findings.error("label.column", "label.column is empty")
    for key in ("positive_value", "unlabeled_value"):
        if is_blank(label.get(key)):
            findings.error(f"label.{key}", f"label.{key} is empty")
    if same_value(label.get("positive_value"), label.get("unlabeled_value")):
        findings.error("label.distinct", "positive_value and unlabeled_value must differ")
    if is_blank(label.get("positive_definition")):
        findings.error(
            "label.positive_definition",
            "label.positive_definition is empty: state how positives were assigned "
            "(e.g. cell contains a known deposit of commodity X, source, date, buffer rule)",
        )
    if label.get("unlabeled_is_verified_negative") is not False:
        findings.error(
            "label.unlabeled_is_verified_negative",
            "this workflow is positive-unlabeled: set label.unlabeled_is_verified_negative to false. "
            "If you truly have verified negatives, that is a different problem design and needs its own plan.",
        )

    columns = features.get("columns")
    if not isinstance(columns, list) or not columns or not all(isinstance(c, str) and c for c in columns):
        findings.error("features.columns", "features.columns must be a non-empty list of column names chosen by you")
        columns = []
    if len(set(columns)) != len(columns):
        findings.error("features.duplicates", "features.columns contains duplicate names")
    units = features.get("units") if isinstance(features.get("units"), dict) else {}
    missing_units = [c for c in columns if is_blank(units.get(c))]
    if missing_units:
        findings.error(
            "features.units",
            "features.units needs an entry for every feature (use \"dimensionless\" or \"category-code\" when apt): "
            + ", ".join(missing_units),
        )
    for key in ("log1p_columns", "winsorize_columns"):
        listed = features.get(key, [])
        if not isinstance(listed, list):
            findings.error(f"features.{key}", f"features.{key} must be a list")
            continue
        unknown = [c for c in listed if c not in columns]
        if unknown:
            findings.error(f"features.{key}", f"features.{key} lists columns not in features.columns: {unknown}")
    threshold = features.get("missing_indicator_threshold")
    if not isinstance(threshold, (int, float)) or not 0 <= threshold <= 1:
        findings.error("features.missing_indicator_threshold", "features.missing_indicator_threshold must be a number in [0, 1]")
    reserved = {coords.get("x_column"), coords.get("y_column"), label.get("column")}
    if len(reserved) != 3:
        findings.error("coordinates.distinct", "x, y and label must use distinct columns")
    leaked = [c for c in columns if c in reserved]
    if leaked:
        findings.error("features.reserved", f"label/coordinate columns must not be features: {leaked}")

    block_size = cv.get("block_size")
    if not isinstance(block_size, (int, float)) or isinstance(block_size, bool) or not math.isfinite(block_size) or block_size <= 0:
        findings.error("spatial_cv.block_size", "spatial_cv.block_size must be a positive number chosen for your area")
    if cv.get("block_size_unit") not in ("m", "km"):
        findings.error("spatial_cv.block_size_unit", "spatial_cv.block_size_unit must be 'm' or 'km'")
    if is_blank(cv.get("block_size_rationale")):
        findings.error(
            "spatial_cv.block_size_rationale",
            "spatial_cv.block_size_rationale is empty: say where the size comes from (variogram range, "
            "geological domain scale, or 'provisional, not yet analysed'). The reference 50 km is not a default.",
        )
    for key in ("n_outer_folds", "n_inner_folds"):
        if not isinstance(cv.get(key), int) or isinstance(cv.get(key), bool) or cv.get(key) < 2:
            findings.error(f"spatial_cv.{key}", f"spatial_cv.{key} must be an integer >= 2")
    if not isinstance(cv.get("random_state"), int) or isinstance(cv.get("random_state"), bool):
        findings.error("spatial_cv.random_state", "spatial_cv.random_state must be an integer (recorded seed)")

    methods = config.get("methods")
    if not isinstance(methods, list) or not methods or any(m not in METHODS for m in methods):
        findings.error("methods", f"methods must be a non-empty subset of {list(METHODS)}")
    alpha, delta = conformal.get("alpha"), conformal.get("delta")
    for key, value in (("alpha", alpha), ("delta", delta)):
        if not isinstance(value, (int, float)) or isinstance(value, bool) or not 0 < value < 1:
            findings.error(f"conformal.{key}", f"conformal.{key} must be a number in (0, 1)")
    if conformal.get("path") not in CONFORMAL_PATHS:
        findings.error("conformal.path", f"conformal.path must be one of {list(CONFORMAL_PATHS)}")

    if conformal.get("path") in ("default", "both") and isinstance(cv.get("n_inner_folds"), int) and cv["n_inner_folds"] < 3:
        findings.error("conformal.inner_folds", "default path needs >=3 inner folds for separate train/calibration/test; pooled_oof can use 2")
    if grid.get("equal_area_cells") is not True:
        findings.warn(
            "grid.equal_area_cells",
            "grid.equal_area_cells is not true: cell-count percentages (zone area %, lift tiers, capture per area) "
            "cannot be read as area fractions. Report counts, or weight by true cell area.",
        )
    if findings.count("error"):
        return None
    return {
        "data": data, "coords": coords, "label": label, "features": features,
        "cv": cv, "grid": grid, "conformal": conformal, "tokens": set(tokens),
        "columns": columns,
    }


def scan_csv(csv_path, spec, findings):
    """Single streaming pass over the CSV. Returns summary dict or None."""
    data, coords, label = spec["data"], spec["coords"], spec["label"]
    tokens, columns = spec["tokens"], spec["columns"]
    x_col, y_col, label_col = coords["x_column"], coords["y_column"], label["column"]
    delimiter = data.get("delimiter") or ","
    encoding = data.get("encoding") or "utf-8"
    unit_m = UNIT_TO_METRE[coords["unit"]]
    block_m = spec["cv"]["block_size"] * (1000.0 if spec["cv"]["block_size_unit"] == "km" else 1.0)
    block_coord = block_m / unit_m

    try:
        handle = open(csv_path, "r", encoding=encoding, newline="")
    except OSError as exc:
        findings.error("data.open", f"cannot open CSV: {exc}")
        return None
    with handle:
        reader = csv.reader(handle, delimiter=delimiter)
        try:
            header = next(reader)
        except StopIteration:
            findings.error("data.empty", "CSV is empty")
            return None
        except UnicodeDecodeError as exc:
            findings.error("data.encoding", f"cannot decode CSV as {encoding}: {exc}")
            return None
        header = [h.lstrip("﻿") if i == 0 else h for i, h in enumerate(header)]
        if len(set(header)) != len(header):
            dup = sorted({h for h in header if header.count(h) > 1})
            findings.error("data.header_duplicates", f"duplicate column names in CSV header: {dup}")
            return None
        required = [x_col, y_col, label_col] + columns
        absent = [c for c in required if c not in header]
        if absent:
            findings.error(
                "data.columns_missing",
                f"declared columns not in CSV: {absent}. (The reference code silently drops missing "
                "features in get_feature_matrix; this helper refuses instead.)",
            )
            return None
        index = {name: header.index(name) for name in required}

        n_rows = n_pos = n_unl = 0
        bad_label, bad_coord, short_rows = [], [], 0
        coord_seen, dup_coords = {}, 0
        xs_min = ys_min = math.inf
        xs_max = ys_max = -math.inf
        rows_xy_label = []
        stats = {c: {"missing": 0, "non_numeric": 0, "min": math.inf, "max": -math.inf, "examples": []} for c in columns}

        try:
            for line_no, row in enumerate(reader, start=2):
                if not row or all(cell.strip() == "" for cell in row):
                    continue
                if len(row) < len(header):
                    short_rows += 1
                    row = row + [""] * (len(header) - len(row))
                n_rows += 1

                cell = row[index[label_col]].strip()
                is_pos = same_value(cell, label["positive_value"]) and cell not in tokens
                is_unl = same_value(cell, label["unlabeled_value"]) and cell not in tokens
                if is_pos:
                    n_pos += 1
                elif is_unl:
                    n_unl += 1
                elif len(bad_label) < 5:
                    bad_label.append((line_no, cell))
                x = to_float(row[index[x_col]])
                y = to_float(row[index[y_col]])
                if x is None or y is None:
                    if len(bad_coord) < 5:
                        bad_coord.append(line_no)
                    rows_xy_label.append(None)
                else:
                    xs_min, xs_max = min(xs_min, x), max(xs_max, x)
                    ys_min, ys_max = min(ys_min, y), max(ys_max, y)
                    key = (x, y)
                    if key in coord_seen:
                        dup_coords += 1
                    else:
                        coord_seen[key] = line_no
                    rows_xy_label.append((x, y, is_pos))

                for col in columns:
                    text = row[index[col]].strip()
                    entry = stats[col]
                    if text in tokens:
                        entry["missing"] += 1
                        continue
                    value = to_float(text)
                    if value is None:
                        entry["non_numeric"] += 1
                        if len(entry["examples"]) < 3:
                            entry["examples"].append(text)
                        continue
                    entry["min"] = min(entry["min"], value)
                    entry["max"] = max(entry["max"], value)
        except UnicodeDecodeError as exc:
            findings.error("data.encoding", f"cannot decode CSV as {encoding}: {exc}")
            return None
        except csv.Error as exc:
            findings.error("data.csv", f"CSV parse error: {exc}")
            return None

    if n_rows == 0:
        findings.error("data.empty", "CSV has a header but no data rows")
        return None
    if short_rows:
        findings.warn("data.short_rows", f"{short_rows} rows have fewer cells than the header (treated as empty cells)")

    n_other = n_rows - n_pos - n_unl
    if n_other:
        findings.error(
            "label.values",
            f"{n_other} rows have a label that is neither positive_value nor unlabeled_value "
            f"(first cases line,value: {bad_label}). Missing or third-class labels must be resolved explicitly.",
        )
    if n_pos == 0:
        findings.error("label.no_positives", "no positive rows found with the declared positive_value")
    if n_unl == 0:
        findings.error("label.no_unlabeled", "no unlabeled rows found with the declared unlabeled_value")

    n_bad_coord = sum(1 for item in rows_xy_label if item is None)
    if n_bad_coord:
        findings.error("coordinates.values", f"{n_bad_coord} rows have missing/non-numeric coordinates (first lines: {bad_coord})")
    elif abs(xs_min) <= 180 and abs(xs_max) <= 180 and abs(ys_min) <= 90 and abs(ys_max) <= 90:
        findings.warn(
            "coordinates.degree_like",
            f"coordinate ranges x[{xs_min}, {xs_max}] y[{ys_min}, {ys_max}] look like degrees although a "
            "projected CRS is declared. Check the columns/CRS.",
        )
    if dup_coords:
        findings.warn(
            "coordinates.duplicates",
            f"{dup_coords} rows repeat an earlier (x, y). They always fall in the same block, but they double-count "
            "cells and positives in every metric and area share. "
            "Decide: aggregate, drop, or justify.",
        )

    feature_summary = {}
    for col in columns:
        entry = stats[col]
        n_valid = n_rows - entry["missing"] - entry["non_numeric"]
        rate = entry["missing"] / n_rows
        feature_summary[col] = {
            "missing_rate": round(rate, 6),
            "non_numeric": entry["non_numeric"],
            "min": entry["min"] if n_valid else None,
            "max": entry["max"] if n_valid else None,
            "unit": spec["features"]["units"].get(col),
        }
        if entry["non_numeric"]:
            findings.error(
                "features.non_numeric",
                f"feature '{col}': {entry['non_numeric']} non-numeric values not listed in data.missing_tokens "
                f"(e.g. {entry['examples']}). Encode categories yourself or add the token explicitly.",
            )
        if n_valid == 0:
            findings.error("features.all_missing", f"feature '{col}' has no valid values")
        elif entry["min"] == entry["max"]:
            findings.warn("features.constant", f"feature '{col}' is constant ({entry['min']})")
        if rate > 0.5:
            findings.warn("features.high_missing", f"feature '{col}' is {rate:.1%} missing; mean imputation will dominate it")
        if col in spec["features"].get("log1p_columns", []) and n_valid and entry["min"] <= -1:
            findings.error("features.log1p_domain", f"feature '{col}' is in log1p_columns but has min {entry['min']} <= -1")
    sentinel_like = [c for c, s in feature_summary.items() if s["min"] in (-9999.0, -99999.0, -999.0) or s["max"] in (9999.0, 99999.0)]
    if sentinel_like:
        findings.warn(
            "features.sentinel_like",
            f"features with sentinel-looking extremes (-9999/-999/9999...): {sentinel_like}. If these mean 'no data', "
            "add them to data.missing_tokens AND note that the reference code reads the CSV with pandas defaults, "
            "so the sentinel must also be handled in pipeline/ (see plan).",
        )
    unused = [h for h in header if h not in required]
    if unused:
        findings.info("features.unused_columns", f"columns present but not selected (by your choice): {unused}")

    # spatial block and positive support
    support = None
    if not n_bad_coord and n_pos:
        blocks = {}
        for item in rows_xy_label:
            x, y, is_pos = item
            key = (int((x - xs_min) // block_coord), int((y - ys_min) // block_coord))
            total, pos = blocks.get(key, (0, 0))
            blocks[key] = (total + 1, pos + (1 if is_pos else 0))
        n_blocks = len(blocks)
        pos_blocks = sum(1 for total, pos in blocks.values() if pos > 0)
        k_out, k_in = spec["cv"]["n_outer_folds"], spec["cv"]["n_inner_folds"]
        alpha, delta = spec["conformal"]["alpha"], spec["conformal"]["delta"]
        hoeffding_min = math.ceil(math.log(2.0 / delta) / (2.0 * alpha * alpha))
        train_pos = n_pos * (k_out - 1) / k_out
        expected = {
            "outer_test_fold": n_pos / k_out,
            "default_path_calibration_fold": train_pos / k_in,
            "pooled_oof_path_calibration_pool": train_pos,
        }
        support = {
            "block_size_in_coordinate_units": block_coord,
            "extent_in_blocks": [int((xs_max - xs_min) // block_coord) + 1, int((ys_max - ys_min) // block_coord) + 1],
            "n_blocks": n_blocks,
            "n_blocks_with_positives": pos_blocks,
            "largest_block_share_of_positives": round(max(pos for _, pos in blocks.values()) / n_pos, 4),
            "hoeffding_min_positives": hoeffding_min,
            "expected_positives_if_balanced": {k: round(v, 1) for k, v in expected.items()},
        }
        if n_blocks < k_out or n_blocks - math.ceil(n_blocks / k_out) < k_in:
            findings.error(
                "spatial_cv.too_few_blocks",
                f"{n_blocks} blocks leave too few training blocks for {k_in} inner folds in at least one of {k_out} outer splits. Use fewer folds, "
                "or accept that nested spatial CV is not feasible for this extent.",
            )
        if pos_blocks < k_out:
            findings.error(
                "spatial_cv.positive_blocks",
                f"positives occur in only {pos_blocks} blocks but n_outer_folds={k_out}: some test folds would have no positives.",
            )
        elif pos_blocks < k_out * k_in:
            findings.warn(
                "spatial_cv.positive_blocks",
                f"positives occur in {pos_blocks} blocks: inspect actual inner-fold positive counts after partitioning; "
                "the product of fold counts is not a necessary feasibility bound.",
            )
        if support["largest_block_share_of_positives"] > 0.5:
            findings.warn("spatial_cv.clustered_positives", "one block holds more than half of all positives; fold metrics will be dominated by where it lands")
        paths = spec["conformal"]["path"]
        if paths in ("default", "both") and expected["default_path_calibration_fold"] < hoeffding_min:
            findings.warn(
                "conformal.support_default",
                f"default cross-conformal path: about {expected['default_path_calibration_fold']:.0f} positives per calibration fold, "
                f"but alpha={alpha}, delta={delta} needs >= {hoeffding_min} before ANY threshold can satisfy FNR+Hoeffding <= alpha. "
                "Below that, fnr_control_direct falls back to the minimum calibration score; all calibration samples are included, but inclusion of unseen samples is not guaranteed.",
            )
        if paths in ("pooled_oof", "both") and expected["pooled_oof_path_calibration_pool"] < hoeffding_min:
            findings.warn(
                "conformal.support_pooled_oof",
                f"pooled-OOF path: about {expected['pooled_oof_path_calibration_pool']:.0f} training positives per outer fold "
                f"< {hoeffding_min} needed for a non-vacuous threshold at alpha={alpha}, delta={delta}.",
            )
        if expected["outer_test_fold"] < 10:
            findings.warn(
                "label.test_support",
                f"about {expected['outer_test_fold']:.0f} positives per outer test fold: PR-AUC, coverage and capture will have wide, "
                "unstable fold-to-fold variation. Report per-fold counts next to every metric.",
            )
    prevalence = n_pos / n_rows
    if n_pos and n_pos < 30:
        findings.warn("label.few_positives", f"only {n_pos} positives in total; treat any model result as exploratory")

    return {
        "n_rows": n_rows,
        "n_positive": n_pos,
        "n_unlabeled": n_unl,
        "labelled_positive_rate": round(prevalence, 6),
        "extent": {"x": [xs_min, xs_max], "y": [ys_min, ys_max]} if not n_bad_coord else None,
        "duplicate_coordinate_rows": dup_coords,
        "features": feature_summary,
        "spatial_support": support,
    }


def run_validation(config_path):
    config_path = Path(config_path).expanduser().resolve()
    config = load_json_file(config_path)
    findings = Findings()
    spec = check_config_shape(config, findings)
    summary, csv_path, csv_hash = None, None, None
    if spec is not None:
        csv_path = Path(spec["data"]["csv_path"]).expanduser()
        if not csv_path.is_absolute():
            csv_path = (config_path.parent / csv_path).resolve()
        if not csv_path.is_file():
            findings.error("data.csv_path", f"CSV not found: {csv_path}")
        else:
            summary = scan_csv(csv_path, spec, findings)
            csv_hash = sha256_file(csv_path)
    report = {
        "schema_version": SCHEMA_VERSION,
        "generated": now_iso(),
        "config_path": str(config_path),
        "config_sha256": sha256_file(config_path),
        "csv_path": str(csv_path) if csv_path else None,
        "csv_sha256": csv_hash,
        "passed": findings.count("error") == 0,
        "scope_note": (
            "Checks the declared data contract only. It does not test label quality, feature relevance, "
            "spatial independence of folds, or suitability of the reference method."
        ),
        "counts": {level: findings.count(level) for level in ("error", "warning", "info")},
        "crs_check": findings.crs_check,
        "findings": findings.items,
        "summary": summary,
    }
    return config, spec, report


def print_findings(report):
    for item in report["findings"]:
        print(f"[{item['level'].upper():7}] {item['code']}: {item['message']}")
    counts = report["counts"]
    print(f"-- errors={counts['error']} warnings={counts['warning']} info={counts['info']}")


def cmd_validate(args):
    _, _, report = run_validation(args.config)
    report_path = Path(args.report) if args.report else Path(report["config_path"]).parent / "validation-report.json"
    write_json_file(report_path, report_for_disk(report, report_path.resolve().parent))
    print_findings(report)
    summary = report["summary"]
    if summary:
        print(
            f"rows={summary['n_rows']} positives={summary['n_positive']} unlabeled={summary['n_unlabeled']} "
            f"labelled-positive rate={summary['labelled_positive_rate']:.4%}"
        )
        if summary["spatial_support"]:
            s = summary["spatial_support"]
            print(f"blocks={s['n_blocks']} with positives={s['n_blocks_with_positives']} extent(blocks)={s['extent_in_blocks']}")
    print(f"report: {report_path}")
    if report["passed"]:
        print("RESULT: data contract checks passed (errors=0). This is not a scientific validation; review warnings, then run plan.")
        return 0
    print("RESULT: FAILED. Fix the errors above; plan is blocked until then.")
    return 1


