def render_pipeline_config(config, spec, csv_path):
    cv, features, conformal = spec["cv"], spec["features"], spec["conformal"]
    unit_m = UNIT_TO_METRE[spec["coords"]["unit"]]
    block_m = cv["block_size"] * (1000.0 if cv["block_size_unit"] == "km" else 1.0)
    # reference code computes block edge = block_size_km * 1000 in COORDINATE units
    effective_block_size_km = block_m / unit_m / 1000.0
    bootstrap = config.get("bootstrap") or {}
    optuna = config.get("optuna") or {}
    seed = cv["random_state"]
    rendered = {
        "paths": {"original_data": str(csv_path), "reference_folds": None},
        "output_dirs": REFERENCE_STATIC_CONFIG["output_dirs"],
        "data": {
            "target_column": spec["label"]["column"],
            "coordinate_columns": [spec["coords"]["x_column"], spec["coords"]["y_column"]],
            "feature_columns": spec["columns"],
            "proximity_features": features.get("log1p_columns", []),
            "winsorize_features": features.get("winsorize_columns", []),
            "missing_indicator_threshold": features["missing_indicator_threshold"],
        },
        "spatial_cv": {
            "block_size_km": effective_block_size_km,
            "n_outer_folds": cv["n_outer_folds"],
            "n_inner_folds": cv["n_inner_folds"],
            "stratify": True,
            "random_state": seed,
        },
        "optuna": {
            "n_trials": optuna.get("n_trials", 30), "sampler": "TPE", "pruner": "MedianPruner",
            "pruner_n_startup_trials": 5, "pruner_n_warmup_steps": 10, "direction": "maximize",
            "objective_metric": "pr_auc", "timeout_seconds": None, "n_jobs": 1,
        },
        "bootstrap": {"n_bootstraps": bootstrap.get("n_bootstraps", 50), "random_state": bootstrap.get("random_state", seed)},
        "conformal": {"alpha": conformal["alpha"], "delta": conformal["delta"], "n_iterations": conformal.get("n_iterations", 20)},
        "zone_method": REFERENCE_STATIC_CONFIG["zone_method"],
        "practical_zone_modes": REFERENCE_STATIC_CONFIG["practical_zone_modes"],
        "zone_thresholds": REFERENCE_STATIC_CONFIG["zone_thresholds"],
        "zone_definitions": REFERENCE_STATIC_CONFIG["zone_definitions"],
        "methods": config["methods"],
        "visualization": REFERENCE_STATIC_CONFIG["visualization"],
        "logging": REFERENCE_STATIC_CONFIG["logging"],
        "random_seeds": {"numpy": seed, "sklearn": seed, "optuna": seed, "bootstrap": bootstrap.get("random_state", seed)},
    }
    header = [
        "# Rendered by the reference-case helper from mpm-config.json. Edit mpm-config.json and re-run plan --apply.",
        "# zone_* / visualization values are the reference study's settings, not recommendations.",
    ]
    if unit_m != 1.0:
        header.append(
            f"# NOTE coordinates are in '{spec['coords']['unit']}': block_size_km below is an EFFECTIVE value "
            f"({effective_block_size_km}) so that block_size_km*1000 coordinate units == {block_m} projected-coordinate metres "
            "(a unit conversion, not a ground-distance guarantee)."
        )
    return "\n".join(header + to_yaml(rendered)) + "\n", effective_block_size_km


def collect_adaptations(config, spec, report):
    """Items where the copied reference code will not do the right thing as-is."""
    items = []
    label = spec["label"]
    if not (same_value(label["positive_value"], 1) and same_value(label["unlabeled_value"], 0)):
        items.append(
            "BLOCKER label encoding: reference code uses the target column as numeric 0/1 (sums it, compares == 1). "
            f"Your values are positive={label['positive_value']!r}, unlabeled={label['unlabeled_value']!r}. Derive a 0/1 column in a "
            "NEW file (keep the source), point data.csv_path at it, and record the derivation."
        )
    if spec["data"].get("delimiter", ",") != "," or spec["data"].get("encoding", "utf-8").lower() not in ("utf-8", "utf-8-sig"):
        items.append("BLOCKER CSV delimiter/encoding: reference pandas loaders use comma and UTF-8 defaults; normalize a separate CSV or adapt every loader before running.")
    custom_tokens = sorted(t for t in spec["tokens"] if t not in ("", "NA", "NaN", "nan", "N/A", "NULL", "null", "#N/A", "n/a", "<NA>", "None"))
    if custom_tokens:
        items.append(
            f"BLOCKER missing tokens {custom_tokens}: reference loaders call pandas.read_csv with defaults "
            "(scripts/utils/data_utils.py:load_original_data, scripts/fold_generation/create_outer_folds.py:main), so these "
            "would be read as real values. Pass na_values in both places in pipeline/ or write a cleaned copy of the CSV."
        )
    crs_check = report.get("crs_check") or {}
    if crs_check.get("status") == "declared-unverified":
        items.append(
            f"BLOCKER CRS properties unverified ({crs_check.get('backend')}): the declared CRS was not parsed, so projected "
            "type, axis unit and axis order are unconfirmed. Re-run validate where pyproj is importable, or set "
            "coordinates.crs_verified_by to the independent check you made. plan --apply is refused until then."
        )
    if UNIT_TO_METRE[spec["coords"]["unit"]] != 1.0:
        items.append(
            "CHECK coordinate unit is not metres: plan --apply writes an effective block_size_km so the block edge is right, "
            "but every log line / figure label in pipeline/ that says 'km' or 'm' will be wrong until adapted."
        )
    if report["summary"] and report["summary"]["duplicate_coordinate_rows"]:
        items.append("DECIDE duplicate coordinates: resolve before fold generation (folds are assigned per row).")
    items.extend([
        "KNOWN reference code identifies rows by pandas positional index of the CSV ('index' / 'original_index' in fold files). "
        "Do not reorder, filter or re-export the CSV after creating folds; status compares the CSV hash for this reason.",
        "KNOWN scripts/fold_generation/create_outer_folds.py reads paths.original_data relative to the current directory while "
        "data_utils.load_original_data resolves it against pipeline/. plan --apply therefore writes an absolute path.",
        "KNOWN orchestration (scripts/orchestration/run_single_outer_fold.py, run_all_outer_folds.py) skips stages when an output "
        "file exists, without checking data/config, and main() does not turn a False return into a non-zero exit code. "
        "Prefer the per-stage commands below and check each stage's artifacts.",
        "KNOWN cross_conformal_*.py fix random_state=42 for the XGBoost fits regardless of config seeds.",
        "NOT AVAILABLE deployment prediction for new, unlabeled-area data (fit on all data, score a new grid). Reference "
        "outputs are outer-test-fold predictions only. A predict adapter must be written and checked; see references/modules/modeling.md (skill root).",
        "NOT PORTABLE scripts/analysis/shap_analysis.py, variogram_analysis.py, r*_*.py and scripts/visualization/generate_figure*.py, "
        "_figure_utils.py contain reference-study data paths, column names or EPSG:3857 map assumptions. Generic plots "
        "(plot_cv_metrics, plot_zone_distribution, plot_deposit_capture, plot_spatial_maps) read outputs/ and config only, but are untested on other data.",
