def stage_commands(config, spec):
    k_out = spec["cv"]["n_outer_folds"]
    methods = config["methods"]
    path = spec["conformal"]["path"]
    fold = "$F"
    tune = {"xgboost": "scripts/optuna_optimization/optuna_xgboost.py", "baggingpu_xgboost": "scripts/optuna_optimization/gridsearch_baggingpu_xgboost.py"}
    train = {"xgboost": "scripts/model_training/train_xgboost_bootstrap.py", "baggingpu_xgboost": "scripts/model_training/train_baggingpu_xgboost_bootstrap.py"}
    conf = {"xgboost": "scripts/conformal_calibration/cross_conformal_xgboost.py", "baggingpu_xgboost": "scripts/conformal_calibration/cross_conformal_baggingpu.py"}
    conf_oof = {"xgboost": "scripts/conformal_calibration/cross_conformal_oof_xgboost.py", "baggingpu_xgboost": "scripts/conformal_calibration/cross_conformal_oof_baggingpu.py"}
    run = "uv run python"
    stages = [
        ("1. outer folds (once)", [f"{run} scripts/fold_generation/create_outer_folds.py"],
         "outputs/folds/outer_fold_assignments.csv — inspect positives per fold before going on"),
        (f"2. inner folds (F = 0..{k_out - 1})", ["F=0  # example outer fold; repeat per-fold stages for all folds before aggregation", f"{run} scripts/fold_generation/create_inner_folds.py --outer-fold {fold}"],
         "outputs/folds/inner_folds/outer_fold_F/inner_fold_assignments.csv"),
        ("3. hyperparameter search on inner folds (expensive)", [f"{run} {tune[m]} --outer-fold {fold}" for m in methods],
         "outputs/optuna/xgboost/... or outputs/gridsearch/baggingpu_xgboost/.../best_params.json"),
        ("4. bootstrap ensemble on outer-train, predict outer-test (expensive)", [f"{run} {train[m]} --outer-fold {fold}" for m in methods],
         "outputs/models/METHOD/outer_fold_F/bootstrap_predictions.npz"),
    ]
    if path in ("default", "both"):
        stages.append((
            "5a. cross-conformal, DEFAULT path (each iteration: inner train / one calibration fold / one inner test fold; median params)",
            [f"{run} {conf[m]} --outer-fold {fold}" for m in methods]
            + [f"{run} scripts/test_evaluation/evaluate_test_fold.py --outer-fold {fold} --method {m}" for m in methods]
            + [f"{run} scripts/test_evaluation/compute_deposit_capture.py --outer-fold {fold} --method {m}" for m in methods],
            "outputs/conformal/, outputs/test_evaluation/, outputs/aggregated/  (this is the path run_single_outer_fold.py calls)",
        ))
    if path in ("pooled_oof", "both"):
        stages.append((
            "5b. cross-conformal, POOLED-OOF path (inner out-of-fold predictions pooled; one Platt fit + one FNR threshold)",
            [f"{run} {conf_oof[m]} --outer-fold {fold}" for m in methods]
            + [f"{run} scripts/test_evaluation/evaluate_test_fold_oof.py --outer-fold {fold} --method {m}" for m in methods],
            "outputs/conformal_oof/, outputs/test_evaluation_oof/, outputs/aggregated_oof/  (hard-coded dirs; never mix with 5a artifacts)",
        ))
    aggregation = []
    if path in ("default", "both"):
        aggregation += [f"{run} scripts/result_aggregation/aggregate_fold_results.py --method {m}" for m in methods]
    if path in ("pooled_oof", "both"):
        aggregation += [f"{run} scripts/result_aggregation/aggregate_oof_results.py --method {m}" for m in methods]
    stages.append(("6. aggregate ONCE, only after every outer fold completed steps 2–5", aggregation,
                   "outputs/aggregated/ for default; outputs/aggregated_oof/ for pooled OOF"))
    if path in ("default", "both"):
        stages.append(("7. DEFAULT-path generic plots (not pooled-OOF plots; untested on non-reference data)",
            [f"{run} scripts/visualization/plot_cv_metrics.py", f"{run} scripts/visualization/plot_zone_distribution.py",
             f"{run} scripts/visualization/plot_deposit_capture.py", f"{run} scripts/visualization/plot_spatial_maps.py"],
            "outputs/figures/; adapt readers explicitly to plot pooled-OOF outputs"))
    else:
        stages.append(("7. pooled-OOF visualization requires reader adaptation", [],
            "Do not run generic default-path plots unchanged: they read outputs/aggregated/. Adapt to aggregated_oof/ and verify schema first."))
    return stages


def cmd_plan(args):
    config, spec, report = run_validation(args.config)
    workspace = Path(report["config_path"]).parent
    write_json_file(workspace / "validation-report.json", report_for_disk(report, workspace))
    if not report["passed"]:
        print_findings(report)
        print("RESULT: plan BLOCKED by validation errors. No plan or pipeline config was written.")
        return 1

    csv_path = Path(report["csv_path"])
    yaml_text, effective_block = render_pipeline_config(config, spec, csv_path)
    adaptations = collect_adaptations(config, spec, report)
    blockers = [a for a in adaptations if a.startswith("BLOCKER")]
    stages = stage_commands(config, spec)
    pipeline_dir = workspace / "pipeline"
    warnings = [f for f in report["findings"] if f["level"] == "warning"]
    summary = report["summary"]

    lines = [
        f"# MPM plan — {config.get('project_name') or workspace.name}",
        "",
        f"Generated {report['generated']} by the reference-case helper. **This is a plan, not a result.** Nothing was installed, trained or evaluated.",
        "",
        "## Inputs (recorded)",
        f"- config: `{rel_to(report['config_path'], workspace)}` sha256 `{report['config_sha256']}` (paths relative to this workspace)",
        f"- data: `{rel_to(report['csv_path'], workspace)}` sha256 `{report['csv_sha256']}` (read-only; never modified by the helper)",
        f"- rows {summary['n_rows']}, positives {summary['n_positive']}, unlabeled {summary['n_unlabeled']} "
        f"(labelled-positive rate {summary['labelled_positive_rate']:.4%})",
        f"- CRS {spec['coords']['crs']} unit {spec['coords']['unit']}; block {spec['cv']['block_size']} {spec['cv']['block_size_unit']} "
        f"— rationale: {spec['cv']['block_size_rationale']}",
        f"- folds {spec['cv']['n_outer_folds']} outer x {spec['cv']['n_inner_folds']} inner, seed {spec['cv']['random_state']}; "
        f"methods {config['methods']}; conformal path `{spec['conformal']['path']}` alpha {spec['conformal']['alpha']} delta {spec['conformal']['delta']}",
        f"- features ({len(spec['columns'])}): {', '.join(spec['columns'])}",
        "",
        "## Readiness",
    ]
    if blockers:
        lines.append(f"**NOT RUNNABLE AS-IS: {len(blockers)} blocker(s) below must be resolved in the workspace first.**")
    else:
        lines.append("No blocker detected by the helper. That only means the copied code should be able to *read* this data; it has not been run.")
    lines += ["", "## Validation warnings to resolve or justify"]
    lines += [f"- `{w['code']}` {w['message']}" for w in warnings] or ["- none"]
    lines += ["", "## Adaptation needed / known limits of the copied reference code"]
    lines += [f"- {a}" for a in adaptations]
    lines += ["", "## Unvalidated points (must stay visible in any report)"]
    lines += [f"- {p}" for p in UNVALIDATED_POINTS]
    lines += [
        "", "## Stage commands",
        f"Run inside `{rel_to(pipeline_dir, workspace)}/` (in this workspace) after `plan --apply` has rendered `config/config.yaml`. The first `uv run python` there "
        "creates `pipeline/.venv` from `pipeline/uv.lock` (local to the workspace; needs network or a warm uv cache). "
        "Start with ONE outer fold and ONE method, reduced `optuna.n_trials` / `bootstrap.n_bootstraps` if you only want a smoke run "
        "— and label such a run as a smoke run.",
        "",
    ]
    for title, commands, artifacts in stages:
        lines.append(f"### {title}")
        lines.append("```bash")
        lines.extend(commands)
        lines.append("```")
        lines.append(f"Artifacts: {artifacts}")
        lines.append("")
    lines += [
        "## Record keeping",
        "- Keep `plan.json`, `validation-report.json`, `pipeline/config/config.yaml` and `adaptations.md` with the outputs.",
        "- If the CSV or mpm-config.json changes, re-run plan and delete or move `pipeline/outputs/` (stages skip on file existence).",
        "- Held-out discipline: outer test folds are for final reporting only. Do not tune features, block size, thresholds or zones on them.",
        "",
    ]
    (workspace / "plan.md").write_text("\n".join(lines), encoding="utf-8")

    applied = False
    rendered_path = workspace / "pipeline-config.rendered.yaml"
    rendered_path.write_text(yaml_text, encoding="utf-8")
    crs_blocked = any(b.startswith("BLOCKER CRS properties unverified") for b in blockers)
    if args.apply and crs_blocked:
        print("RESULT: --apply refused: CRS properties are unverified (see plan.md blocker).")
    if args.apply and not crs_blocked:
        target = pipeline_dir / "config" / "config.yaml"
        if not target.parent.is_dir():
            raise UsageError(f"{target.parent} not found; run init first or apply the rendered YAML yourself: {rendered_path}")
        target.write_text(yaml_text, encoding="utf-8")
        applied = True

    write_json_file(workspace / "plan.json", {
        "schema_version": SCHEMA_VERSION,
        "generated": report["generated"],
        "config_sha256": report["config_sha256"],
        "paths_relative_to": "this file's directory",
        "csv_path": rel_to(report["csv_path"], workspace),
        "csv_sha256": report["csv_sha256"],
        "seeds": {"spatial_cv": spec["cv"]["random_state"], "bootstrap": (config.get("bootstrap") or {}).get("random_state", spec["cv"]["random_state"]),
                  "conformal_xgboost_fit": "fixed 42 in reference code"},
        "effective_block_size_km_for_reference_code": effective_block,
        "methods": config["methods"],
        "conformal_path": spec["conformal"]["path"],
        "n_outer_folds": spec["cv"]["n_outer_folds"],
        "blockers": blockers,
        "pipeline_config_applied": applied,
        "pipeline_config_sha256": sha256_file(pipeline_dir / "config" / "config.yaml") if applied else None,
        "executed_stages": [],
    })

    print_findings(report)
    print(f"plan: {workspace / 'plan.md'}")
    print(f"rendered pipeline config: {rendered_path}" + (f" (applied to {pipeline_dir / 'config' / 'config.yaml'})" if applied else " (not applied; use --apply)"))
    if blockers:
        print(f"RESULT: plan written, but NOT RUNNABLE AS-IS: {len(blockers)} blocker(s). See plan.md.")
    else:
        print("RESULT: plan written. No stage has been run; the plan lists adaptation items and unvalidated points.")
    return 1 if args.apply and crs_blocked else 0


