def cmd_status(args):
    workspace = Path(args.workspace).expanduser().resolve()
    plan_path = workspace / "plan.json"
    if not plan_path.is_file():
        print(f"no plan.json in {workspace}: run validate and plan first")
        return 1
    plan = load_json_file(plan_path)
    stale = []
    config_path = workspace / "mpm-config.json"
    if not config_path.is_file():
        stale.append("mpm-config.json missing since plan")
    elif sha256_file(config_path) != plan["config_sha256"]:
        stale.append("mpm-config.json changed since plan")
    csv_path = workspace / plan["csv_path"]  # relative to the workspace; older plans stored an absolute path
    if not csv_path.is_file():
        stale.append(f"data file missing: {csv_path}")
    elif sha256_file(csv_path) != plan["csv_sha256"]:
        stale.append("data CSV changed since plan")

    applied_path = workspace / "pipeline" / "config" / "config.yaml"
    if plan.get("pipeline_config_applied"):
        if not applied_path.is_file() or sha256_file(applied_path) != plan.get("pipeline_config_sha256"):
            stale.append("applied pipeline/config/config.yaml missing or changed since plan")
    outputs = workspace / "pipeline" / "outputs"
    print(f"workspace: {workspace}")
    print(f"plan generated: {plan['generated']}  conformal path: {plan['conformal_path']}  config applied: {plan['pipeline_config_applied']}")
    for blocker in plan.get("blockers", []):
        print(f"  unresolved at plan time: {blocker}")
    print(f"outer folds file: {'present' if (outputs / 'folds' / 'outer_fold_assignments.csv').is_file() else 'absent'}")
    for method in plan["methods"]:
        tune_dir = "optuna" if method == "xgboost" else "gridsearch"
        for fold in range(plan["n_outer_folds"]):
            name = f"outer_fold_{fold}"
            checks = {
                "inner": outputs / "folds" / "inner_folds" / name / "inner_fold_assignments.csv",
                "tune": outputs / tune_dir / method / name / "best_params.json",
                "boot": outputs / "models" / method / name / "bootstrap_predictions.npz",
                "conf": outputs / "conformal" / method / name / "median_params.json",
                "eval": outputs / "test_evaluation" / method / name / "metrics.json",
                "conf_oof": outputs / "conformal_oof" / method / name / "median_params.json",
                "eval_oof": outputs / "test_evaluation_oof" / method / name / "metrics.json",
            }
            marks = " ".join(f"{key}={'Y' if path.is_file() else '-'}" for key, path in checks.items())
            print(f"  {method:18} {name}: {marks}")
    print("note: 'Y' means the file exists, not that the stage was correct or used the current data/config.")
    if stale:
        for reason in stale:
            print(f"STALE: {reason}")
        print("RESULT: existing outputs may not correspond to current inputs. Re-run plan and move pipeline/outputs/ aside before continuing.")
        return 1
    print("RESULT: inputs unchanged since plan.")
    return 0


