def build_parser():
    parser = argparse.ArgumentParser(
        prog="workflow.py",
        description=__doc__,
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    sub = parser.add_subparsers(dest="command", required=True)
    p_init = sub.add_parser("init", help="create a workspace with a copy of the reference code and a config template")
    p_init.add_argument("--mode", required=True, choices=["narr-reproduction"], help="explicitly select reference-study reproduction, not general MPM")
    p_init.add_argument("workspace", help="new or empty directory outside the installed skill")
    p_init.set_defaults(func=cmd_init)
    p_val = sub.add_parser("validate", help="check CSV + JSON config (data contract only)")
    p_val.add_argument("--config", required=True, help="path to mpm-config.json")
    p_val.add_argument("--report", help="where to write the JSON report (default: next to the config)")
    p_val.set_defaults(func=cmd_validate)
    p_plan = sub.add_parser("plan", help="write plan.md/plan.json with commands, adaptation items and unvalidated points")
    p_plan.add_argument("--config", required=True, help="path to mpm-config.json")
    p_plan.add_argument("--apply", action="store_true", help="also write pipeline/config/config.yaml in the workspace")
    p_plan.set_defaults(func=cmd_plan)
    p_status = sub.add_parser("status", help="list stage artifacts and detect changed data/config")
    p_status.add_argument("--workspace", required=True)
    p_status.set_defaults(func=cmd_status)
    return parser


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        return args.func(args)
    except UsageError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
